using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Threading;
using System.Threading.Tasks;
public class CodexQuotaConfig {public bool Enabled=true,Alerts=true,BackgroundRefresh=true,ResetDetectedAlerts=true;public double FiveHourThreshold=20,WeeklyThreshold=20;public List<double> FiveHourThresholds,WeeklyThresholds;public List<int> ResetReminderPoints;public string Executable="",Home="";public bool ResetReminder=true;public int ResetReminderMinutes=5;public CodexWakeConfig Wake=new CodexWakeConfig();public CodexSubscriptionConfig Subscription=new CodexSubscriptionConfig();public CodexQuotaSnapshot LastObserved;public List<CodexQuotaReset> ResetHistory=new List<CodexQuotaReset>();public List<string> SentResetReminders=new List<string>();}
public class CodexQuotaWindow {public int Minutes;public double Remaining;public DateTime ResetUtc;public bool PendingStart(DateTime now){return Remaining>=99.999&&(ResetUtc<=now||Math.Abs((ResetUtc-now-TimeSpan.FromMinutes(Minutes)).TotalMinutes)<=2);}}
public class CodexQuotaSnapshot {
 public bool RequiresAuthorization;public DateTime CheckedUtc,NextCheckUtc;public string AccountKey="",PlanType="";public string State="等待 Codex 额度采样";public List<CodexQuotaWindow> Windows=new List<CodexQuotaWindow>();
 public double? Remaining(int minutes,DateTime now){var w=Windows.FirstOrDefault(x=>x.Minutes==minutes);return !RequiresAuthorization&&w!=null&&now>=CheckedUtc&&now-CheckedUtc<=TimeSpan.FromMinutes(5)&&(w.ResetUtc>now||w.PendingStart(now))?(double?)w.Remaining:null;}
 public static CodexQuotaSnapshot Parse(string json,DateTime now){var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);object result;if(root.TryGetValue("result",out result))root=(Dictionary<string,object>)result;object buckets;if(root.TryGetValue("rateLimitsByLimitId",out buckets)&&buckets is Dictionary<string,object>){object bucket;if(((Dictionary<string,object>)buckets).TryGetValue("codex",out bucket))root=(Dictionary<string,object>)bucket;else throw new InvalidDataException("未返回 Codex 额度桶");}else if(root.TryGetValue("rateLimits",out result))root=(Dictionary<string,object>)result;
  var snapshot=new CodexQuotaSnapshot{CheckedUtc=now,State="Codex 官方 app-server · 每60秒核验"};foreach(string key in new[]{"primary","secondary"}){object obj;if(!root.TryGetValue(key,out obj)||!(obj is Dictionary<string,object>))continue;var d=(Dictionary<string,object>)obj;object m,u,t;if(!d.TryGetValue("windowDurationMins",out m)||!d.TryGetValue("usedPercent",out u))continue;d.TryGetValue("resetsAt",out t);int minutes=Convert.ToInt32(m);double used=Convert.ToDouble(u);if((minutes!=300&&minutes!=10080)||Double.IsNaN(used)||Double.IsInfinity(used)||used<0||used>100)continue;DateTime reset=t==null?default(DateTime):new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddSeconds(Convert.ToDouble(t));snapshot.Windows.Add(new CodexQuotaWindow{Minutes=minutes,Remaining=100-used,ResetUtc=reset});}if(snapshot.Windows.Count==0)throw new InvalidDataException("Codex 未返回有效的五小时或周额度");if(snapshot.Windows.Any(w=>w.PendingStart(now)))snapshot.State="Codex 官方核验 · 额度可用，等待首次请求启动新周期";else if(snapshot.Windows.Any(w=>w.ResetUtc<=now))snapshot.State="Codex 官方核验 · 等待官方确认新周期";return snapshot;
 }
}
public sealed partial class CodexQuotaReader {
 public readonly QuotaExecutionTrust Trust;
 public CodexQuotaReader(string dataFolder=null){if(dataFolder!=null)Trust=new QuotaExecutionTrust(dataFolder);}
 CodexQuotaSnapshot current=new CodexQuotaSnapshot();DateTime next;int busy,manualRefresh;public string Status="等待 Codex 额度采样";readonly object gate=new object();readonly Dictionary<string,string> alerted=new Dictionary<string,string>();
 public CodexQuotaSnapshot Sample(CodexQuotaConfig cfg){if(!cfg.Enabled)return new CodexQuotaSnapshot{State="Codex 额度监控已关闭"};if((cfg.BackgroundRefresh&&DateTime.UtcNow>=next||Interlocked.CompareExchange(ref manualRefresh,0,0)==1)&&Interlocked.CompareExchange(ref busy,1,0)==0){Interlocked.Exchange(ref manualRefresh,0);next=DateTime.UtcNow.AddSeconds(60);string exe=cfg.Executable,home=cfg.Home;Task.Run(()=>{try{if(Trust==null)throw new QuotaAuthorizationException("额度程序尚未授权。");CodexQuotaSnapshot value;using(var permit=Trust.OpenVerified(exe,home))value=Fetch(permit.Identity.Executable,permit.Identity.Home);lock(gate){current=value;current.NextCheckUtc=next;Status=value.State;}}catch(Exception e){lock(gate){Status="额度暂不可用："+(e is IOException?e.Message:"无法读取 Codex 返回值（"+e.GetType().Name+"）");current=new CodexQuotaSnapshot{CheckedUtc=current.CheckedUtc,Windows=current.Windows,AccountKey=current.AccountKey,RequiresAuthorization=e is QuotaAuthorizationException,State=Status};}}finally{Interlocked.Exchange(ref busy,0);}});}lock(gate){current.NextCheckUtc=cfg.BackgroundRefresh?next:default(DateTime);return current;}}
 public void RefreshNow(){Interlocked.Exchange(ref manualRefresh,1);next=DateTime.MinValue;}
 public static string FindExecutable(string configured){if(!String.IsNullOrWhiteSpace(configured)){configured=QuotaExecutionTrust.LocalPath(configured);if(File.Exists(configured)&&Path.GetExtension(configured).Equals(".exe",StringComparison.OrdinalIgnoreCase))return configured;throw new IOException("指定的 Codex.exe 不存在");}string npm=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),@"npm\node_modules\@openai\codex\node_modules\@openai\codex-win32-x64\vendor\x86_64-pc-windows-msvc\bin\codex.exe");npm=QuotaExecutionTrust.LocalPath(npm);if(File.Exists(npm))return npm;foreach(string path in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){try{string candidate=QuotaExecutionTrust.LocalPath(Path.Combine(path,"codex.exe"));if(File.Exists(candidate))return candidate;}catch(ArgumentException){}}throw new IOException("未找到 Codex.exe，请在额度设置中选择；需已登录 ChatGPT 的 Codex");}
 public static CodexQuotaSnapshot Fetch(string configured){return Fetch(configured,"");}
 public static CodexQuotaSnapshot Fetch(string configured,string codexHome){string exe=FindExecutable(configured);var info=new ProcessStartInfo(exe,"app-server"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};if(!String.IsNullOrWhiteSpace(codexHome)){if(!Directory.Exists(codexHome))throw new IOException("Codex数据目录不存在");info.EnvironmentVariables["CODEX_HOME"]=codexHome;}using(var p=Process.Start(info)){
  try{p.StandardError.ReadToEndAsync();p.StandardInput.WriteLine("{\"id\":1,\"method\":\"initialize\",\"params\":{\"clientInfo\":{\"name\":\"conan-quota\",\"version\":\"5.19.0\"}}}");p.StandardInput.Flush();string accountKey="",planType="";var until=DateTime.UtcNow.AddSeconds(15);while(DateTime.UtcNow<until){var task=p.StandardOutput.ReadLineAsync();int wait=Math.Max(1,(int)(until-DateTime.UtcNow).TotalMilliseconds);if(!task.Wait(wait)||task.Result==null)throw new IOException("Codex 额度服务响应超时");var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(task.Result);object id;if(!d.TryGetValue("id",out id))continue;object error;if(Convert.ToInt32(id)==2){object accountResult;accountKey=d.TryGetValue("result",out accountResult)?AccountFingerprint(accountResult):"";planType=AccountPlan(accountResult);p.StandardInput.WriteLine("{\"id\":3,\"method\":\"account/rateLimits/read\"}");p.StandardInput.Flush();continue;}if(d.TryGetValue("error",out error))throw new IOException("Codex 未能查询额度，请检查登录状态和网络");if(Convert.ToInt32(id)==1){p.StandardInput.WriteLine("{\"method\":\"initialized\",\"params\":{}}");p.StandardInput.WriteLine("{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":false}}");p.StandardInput.Flush();}else if(Convert.ToInt32(id)==3){var snapshot=CodexQuotaSnapshot.Parse(task.Result,DateTime.UtcNow);snapshot.AccountKey=accountKey;snapshot.PlanType=planType;return snapshot;}}throw new IOException("Codex 额度查询超时");}finally{if(!p.HasExited)p.Kill();}}
 }
 public string[] Alerts(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now){var list=new List<string>();if(!cfg.Enabled||!cfg.Alerts||s==null){alerted.Clear();return list.ToArray();}var activeKeys=new HashSet<string>();foreach(int minutes in new[]{300,10080})foreach(double threshold in ThresholdPoints.Effective(minutes==300?cfg.FiveHourThresholds:cfg.WeeklyThresholds,minutes==300?cfg.FiveHourThreshold:cfg.WeeklyThreshold,0,100)){string stateKey=minutes+":"+threshold.ToString(System.Globalization.CultureInfo.InvariantCulture);activeKeys.Add(stateKey);var v=s.Remaining(minutes,now);if(!v.HasValue)continue;if(v.Value>threshold+5){alerted.Remove(stateKey);continue;}var window=s.Windows.First(x=>x.Minutes==minutes);string key=s.AccountKey+":"+window.ResetUtc.Ticks;string previous;if(v.Value<=threshold&&(!alerted.TryGetValue(stateKey,out previous)||previous!=key)){alerted[stateKey]=key;list.Add("Codex "+(minutes==300?"五小时":"周")+"额度仅剩 "+v.Value.ToString("F0")+"%，预警点 "+threshold.ToString("0.##")+"%；距离预计重置还有 "+BubbleLogic.TimeLeft(window.ResetUtc-now)+"。");}}foreach(string key in alerted.Keys.Where(k=>!activeKeys.Contains(k)).ToArray())alerted.Remove(key);return list.ToArray();}

}
